// Sub-component for individual orbiting planets
interface OrbitItemProps {
  category: ServiceCategory;
  angle: number;
  radius: number;
  isActive: boolean;
  onClick: () => void;
}

const OrbitItem: React.FC<OrbitItemProps> = ({ category, angle, radius, isActive, onClick }) => {
  // We want the orbit to rotate slowly.
  // We can achieve this by animating the rotation of a container, 
  // OR by calculating positions in a `useEffect` loop. 
  // Let's use Framer Motion's `animate` on a container value for smooth rotation.

  // Actually, a simpler CSS/Motion approach:
  // Create a container div that rotates. The Item is placed at the edge.
  // The Item then "Counter-Rotates" so text stays upright.

  return (
    <motion.div
      className="absolute top-1/2 left-1/2" // Anchor center
      style={{ width: 0, height: 0 }} // Zero size, used for positioning
      animate={{ rotate: 360 }}
      transition={{ duration: 50, repeat: Infinity, ease: "linear" }}
    >
        {/* The arm/positioner */}
        <div 
            className="absolute -translate-x-1/2 -translate-y-1/2"
            style={{ 
                transform: `rotate(${angle}rad) translate(${radius}px) rotate(-${angle}rad)` 
            }}
        >
           {/* To counteract the parent rotation animation, we apply a reverse rotation animation to this specific node wrapper */}
           <motion.div
              animate={{ rotate: -360 }}
              transition={{ duration: 50, repeat: Infinity, ease: "linear" }}
           >
              <button
                onClick={onClick}
                className={`
                  relative group flex flex-col items-center justify-center
                  w-24 h-24 sm:w-28 sm:h-28 rounded-full 
                  backdrop-blur-md border-2 transition-all duration-300
                  ${isActive 
                    ? `bg-slate-800 border-${category.color.split('-')[1]}-400 shadow-[0_0_30px_rgba(0,0,0,0.5)] scale-110` 
                    : 'bg-slate-900/60 border-slate-700 hover:border-slate-500 hover:bg-slate-800'
                  }
                `}
              >
                {/* Active Indicator Pulse */}
                {isActive && (
                    <span className={`absolute inset-0 rounded-full animate-ping opacity-20 bg-${category.color.split('-')[1]}-500`}></span>
                )}

                {/* Icon */}
                <div className={`mb-2 ${isActive ? 'text-white' : category.color} transition-colors`}>
                  {iconMap[category.icon]}
                </div>

                {/* Label */}
                <span className={`text-xs sm:text-sm font-semibold text-center leading-tight px-1 ${isActive ? 'text-white' : 'text-slate-300'}`}>
                  {category.shortTitle}
                </span>

                {/* Satellite Dots (Decoration) */}
                <div className={`absolute -top-1 -right-1 w-3 h-3 rounded-full bg-${category.color.split('-')[1]}-500 border border-slate-900`} />
              </button>
           </motion.div>
        </div>
    </motion.div>
  );
};

export default Hero;

