import React, { useRef, useState, useEffect } from 'react';
import { motion, useScroll, useTransform, useSpring, useMotionValueEvent, useTime } from 'framer-motion';
import { ScanEye, ShieldCheck, ClipboardCheck, Lightbulb, CheckCircle2 } from 'lucide-react';
import { servicesData } from '../data/services';
import { ServiceCategory } from '../types';
import FloatingParticles from './FloatingParticles';

const LOGO_URL = "https://megama.si/wp-content/uploads/2021/01/cropped-website_logo_transparent_background-1-1.png";

const iconMap: Record<string, React.ReactNode> = {
  ScanEye: <ScanEye size={24} />,
  ShieldCheck: <ShieldCheck size={24} />,
  ClipboardCheck: <ClipboardCheck size={24} />,
