  useEffect(() => {
    // Initial size
    setScreenSize({ width: window.innerWidth, height: window.innerHeight });

    const handleResize = () => setScreenSize({ width: window.innerWidth, height: window.innerHeight });
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const isMobile = screenSize.width < 1024; // lg breakpoint

  // -- Motion Values --

  // Map scrollY to a 0-1 progress value
  // 0 = Start (Orbit), 1 = End (Grid)
  const rawProgress = useTransform(scrollY, [0, 800], [0, 1]);
  const progress = useSpring(rawProgress, { stiffness: 400, damping: 40 });

  // Time for orbit rotation
  const time = useTime();
  const [rotationOffset, setRotationOffset] = useState(0);

  // Freeze time-based rotation as we scroll
  // We use a state update on scroll change to capture the "last" angle so it doesn't jump
  // but for simplicity in this specific "Fly to Grid" effect, we will dampen the time influence.
  const timeFactor = useTransform(progress, [0, 0.2], [1, 0]); // Stop rotating quickly

