// --- Subcomponent for Interpolation Logic ---

interface TransformingItemProps {
  category: ServiceCategory;
  index: number;
  total: number;
  progress: any; // MotionValue
  time: any; // MotionValue
  timeFactor: any; // MotionValue
  screenSize: { width: number; height: number };
  isMobile: boolean;
}

const TransformingItem: React.FC<TransformingItemProps> = ({ 
  category, index, total, progress, time, timeFactor, screenSize, isMobile 
}) => {
  // 1. Calculate Orbit Position
  // We use useTransform to dynamically calculate X/Y based on time and scroll

  const orbitRadius = isMobile ? 140 : 240;
  const angleOffset = (index / total) * Math.PI * 2;

  // 2. Calculate Target Grid Position
  // Desktop: 4 columns centered. 
  // Mobile: Vertical stack below logo.

  let targetX = 0;
  let targetY = 0;

  if (isMobile) {
    // Mobile Stack: Centered horizontally, spaced vertically starting below logo
    // Logo ends at top: ~30px + height ~60px. Start list at ~150px
    const startY = 220;
    const gapY = 280; // Large gap for content cards
    targetX = screenSize.width / 2;
    targetY = startY + (index * gapY);
  } else {
    // Desktop Grid: 4 cols
    // Margin left/right ~50px. 
    // Available width = width - 100. Col width = Avail / 4.
    // Center of col = 50 + ColWidth * index + ColWidth/2
    const margin = 48; // px
    const maxContentWidth = Math.min(screenSize.width, 1280); // max-w-7xl
    const outerMargin = (screenSize.width - maxContentWidth) / 2;
    const effectiveLeft = Math.max(margin, outerMargin + margin);
    const effectiveWidth = screenSize.width - (effectiveLeft * 2);
    const colWidth = effectiveWidth / 4;

    targetX = effectiveLeft + (colWidth * index) + (colWidth / 2);
    targetY = 160; // Fixed header height
  }

  // 3. Motion Values for Position
  const x = useTransform(() => {
    // Current Time Angle
    const t = time.get() / 5000; // Slow down
    const factor = timeFactor.get();
    const currentAngle = angleOffset + (t * factor); // Stops rotating as factor -> 0

    const centerX = screenSize.width / 2;
    const centerY = screenSize.height / 2;

    // Orbit Pos
    const oX = centerX + Math.cos(currentAngle) * orbitRadius;
    const oY = centerY + Math.sin(currentAngle) * orbitRadius;

    // Lerp to Target
    const p = progress.get(); // 0 to 1

    return oX + (targetX - oX) * p;
  });

  const y = useTransform(() => {
    const t = time.get() / 5000;
    const factor = timeFactor.get();
    const currentAngle = angleOffset + (t * factor);

    const centerX = screenSize.width / 2;
    const centerY = screenSize.height / 2;

    const oX = centerX + Math.cos(currentAngle) * orbitRadius;
    const oY = centerY + Math.sin(currentAngle) * orbitRadius;

    const p = progress.get();

    return oY + (targetY - oY) * p;
  });

  // Scale: 1 -> 1 (Maybe slight pulse in grid?)
  // Let's keep scale consistent, or shrink slightly for grid headers
  const scale = useTransform(progress, [0, 1], [1, 0.9]);

  // Visual Shift: In Orbit, it's a bubble. In Grid, it's a Header.
  // We can transition the styling.
  const bgOpacity = useTransform(progress, [0, 1], [0.6, 0]); // Fade out background circle
  const borderOpacity = useTransform(progress, [0, 1], [1, 0]); // Remove border

  return (
    <motion.div
      style={{ x, y, scale, left: 0, top: 0, position: 'absolute' }}
      className="flex flex-col items-center justify-center -translate-x-1/2 -translate-y-1/2 z-50 w-64" // Fixed width to ensure centering
    >
      <motion.div 
        className={`
          flex flex-col items-center justify-center p-4 rounded-full transition-colors
        `}
      >
        {/* Background Circle (Fades out) */}
        <motion.div 
           style={{ opacity: bgOpacity }}
           className={`absolute inset-0 bg-slate-900 rounded-full border border-slate-700`}
        />

        {/* Icon & Text Container */}
        <div className="relative z-10 flex flex-col items-center gap-2">
           <div className={`p-3 rounded-full bg-slate-800/50 backdrop-blur ${category.color} ring-1 ring-white/10 shadow-lg`}>
              {iconMap[category.icon]}
           </div>

           <span className={`text-sm md:text-base font-bold uppercase tracking-wider text-center whitespace-nowrap ${category.color}`}>
             {category.shortTitle}
           </span>
        </div>
      </motion.div>
    </motion.div>
  );
};

