            className="absolute -bottom-10 left-1/2 -translate-x-1/2 text-slate-400 text-sm tracking-widest uppercase font-semibold whitespace-nowrap"
          >
            Quality Assurance
          </motion.div>
        </motion.div>

        {/* ITEMS (Planets/Headers) */}
        <div className="absolute inset-0 z-40 pointer-events-none">
          {screenSize.width > 0 && servicesData.map((category, index) => (
            <TransformingItem 
              key={category.id}
              category={category}
              index={index}
              total={servicesData.length}
              progress={progress}
              time={time}
              timeFactor={timeFactor}
              screenSize={screenSize}
