        >
          <span className="block animate-pulse mb-1">Kliknite na kroge za podrobnosti</span>
          <span className="block opacity-60">ali scrollajte za pregled</span>
        </motion.div>
      </div>
    </div>
  );
};


interface TransformingItemProps {
  category: ServiceCategory;
  index: number;
  total: number;
  progress: any;
  time: any;
  timeFactor: any;
  screenSize: { width: number; height: number };
  isMobile: boolean;
  isActive: boolean;
  onClick: () => void;
}

const TransformingItem: React.FC<TransformingItemProps> = ({ 
  category, index, total, progress, time, timeFactor, screenSize, isMobile, isActive, onClick 
}) => {
  const orbitRadius = isMobile ? 130 : 220;
  const angleOffset = (index / total) * Math.PI * 2;

  // Calculate grid positions
  let targetX = 0;
  let targetY = 0;

  if (isMobile) {
    const startY = 220;
    const gapY = 280; // Matches grid gap
    targetX = screenSize.width / 2;
    targetY = startY + (index * gapY);
  } else {
    const margin = 48;
    const maxContentWidth = Math.min(screenSize.width, 1280); 
    const outerMargin = (screenSize.width - maxContentWidth) / 2;
    const effectiveLeft = Math.max(margin, outerMargin + margin);
    const effectiveWidth = screenSize.width - (effectiveLeft * 2);
    const colWidth = effectiveWidth / 4;
    targetX = effectiveLeft + (colWidth * index) + (colWidth / 2);
    targetY = 160; 
  }

  // Motion Values
  const x = useTransform(() => {
    const t = time.get() / 5000;
    const factor = timeFactor.get();
    const currentAngle = angleOffset + (t * factor);

    const centerX = screenSize.width / 2;
    const centerY = screenSize.height / 2;

    const oX = centerX + Math.cos(currentAngle) * orbitRadius;
    const p = progress.get();
    return oX + (targetX - oX) * p;
  });

  const y = useTransform(() => {
    const t = time.get() / 5000;
    const factor = timeFactor.get();
    const currentAngle = angleOffset + (t * factor);

    const centerX = screenSize.width / 2;
    const centerY = screenSize.height / 2;

    const oY = centerY + Math.sin(currentAngle) * orbitRadius;
    const p = progress.get();
    return oY + (targetY - oY) * p;
  });

  // Scale down slightly when in grid mode
  const scale = useTransform(progress, [0, 1], [1, 0.9]);

  // Styling Transitions
  const bgOpacity = useTransform(progress, [0, 1], [0.6, 0]); 
  const pointerEvents = useTransform(progress, [0.1, 1], ['auto', 'none']);

  return (
    <motion.div
      style={{ x, y, scale, left: 0, top: 0, position: 'absolute', pointerEvents }}
      className="flex flex-col items-center justify-center -translate-x-1/2 -translate-y-1/2 z-50 w-64"
    >
      <button 
        onClick={onClick}
        className={`
           relative group flex flex-col items-center justify-center rounded-full transition-all duration-300
           ${isActive ? 'scale-110 z-50' : 'hover:scale-105'}
        `}
      >
        {/* Background Circle (Fades out in grid) */}
        <motion.div 
           style={{ opacity: bgOpacity }}
           className={`
             absolute inset-0 bg-slate-900 rounded-full border transition-colors duration-300
             ${isActive 
               ? `border-${category.color.split('-')[1]}-400 shadow-[0_0_30px_rgba(0,0,0,0.5)]` 
               : 'border-slate-700 group-hover:border-slate-500 group-hover:bg-slate-800'
             }
           `}
           layoutId={`bg-${category.id}`} // layoutId helps smooth transitions if needed, but here simple style is enough
           // Apply specific dimensions for the "Orbit" state visual
           // We use a fixed size here that matches the Orbit visual, 
           // but the outer div handles position.
           // In Grid state, this fades out, leaving just content.
           initial={false}
           animate={{
             width: isActive ? 110 : 100,
             height: isActive ? 110 : 100,
           }}
        />

        {/* Pulse Effect (Only in orbit) */}
        {isActive && (
            <motion.span 
              style={{ opacity: useTransform(progress, [0, 0.1], [0.2, 0]) }}
              className={`absolute inset-0 rounded-full animate-ping bg-${category.color.split('-')[1]}-500`} 
            />
        )}

        {/* Content */}
        <div className="relative z-10 flex flex-col items-center gap-2 p-4">
           <div className={`
             p-3 rounded-full bg-slate-800/50 backdrop-blur transition-all duration-300
             ${isActive ? 'ring-2 ring-white' : 'ring-1 ring-white/10'}
             ${category.color}
           `}>
              {iconMap[category.icon]}
           </div>

           <span className={`
             text-sm md:text-base font-bold uppercase tracking-wider text-center whitespace-nowrap transition-colors duration-300
             ${isActive ? 'text-white' : category.color}
             ${!isActive && 'text-slate-300'} 
           `}>
             {category.shortTitle}
           </span>
        </div>
      </button>
    </motion.div>
  );
};

